/* Tranh vẽ tay cho các bài thuyết trình mẫu (tab Speech) ở trang Ôn tập nói Mầm non và Lớp 1.
   Tạo tự động: tranh gốc lấy từ trang bài nói của Duy An, tranh khóa l1_ vẽ thêm cho lớp 1.
   Mỗi tranh là một SVG, dùng làm hình của từng câu (trong trang: DZ.tên_tranh). File này tự gắn CSS cho tranh. */
(function(){var s=document.createElement('style');s.textContent="/* Bài Speech: tranh vẽ tay (SVG) và chữ màu */\n.dz-art{display:block;width:112px;height:96px}\n.sk-board:has(.dz-art){grid-template-columns:repeat(auto-fill,minmax(min(100%,320px),1fr))}\n.dz-art.dz-fig{width:120px;height:128px}\n.sk-big .dz-art{width:min(60vw,380px);height:min(36vh,300px);margin:0 auto}\n.sk-big .dz-art.dz-fig{width:min(70vw,460px);height:min(46vh,400px)}\n.dz-fig .lbl text{font-family:\"Baloo 2\",sans-serif;font-weight:800;font-size:22px;fill:#1d2a44}\n.dz-fig .lbl line,.dz-fig .lbl path{stroke:#4a5878;stroke-width:2.5;stroke-dasharray:5 4;fill:none}\n.dz-fig .lbl rect{fill:#fff1a8;stroke:#1d2a44;stroke-width:2.5}\n.dz-fig.focus .lbl{opacity:.25}.dz-fig.focus .lbl.hl{opacity:1}\n.dz-fig.focus .lbl.hl rect{fill:#ff4f86}.dz-fig.focus .lbl.hl text{fill:#fff}\nb.cw,.sk-txt b.cw,.sk-sline b.cw{display:inline-block;padding:0 .35em;border:3px solid #1d2a44;border-radius:10px;line-height:1.2;color:#1d2a44}\nb.cw.gray,.sk-txt b.cw.gray,.sk-sline b.cw.gray{background:#9aa1ad;color:#fff}\nb.cw.green,.sk-txt b.cw.green,.sk-sline b.cw.green{background:#5cc24c;color:#1d2a44}\nb.cw.pink,.sk-txt b.cw.pink,.sk-sline b.cw.pink{background:#ffb3c7;color:#1d2a44}\nb.cw.yellow,.sk-txt b.cw.yellow,.sk-sline b.cw.yellow{background:#ffd23f;color:#1d2a44}\nb.cw.red,.sk-txt b.cw.red,.sk-sline b.cw.red{background:#ef4b4b;color:#fff}\nb.cw.blue,.sk-txt b.cw.blue,.sk-sline b.cw.blue{background:#2f7de1;color:#fff}\nb.cw.purple,.sk-txt b.cw.purple,.sk-sline b.cw.purple{background:#8a4fd8;color:#fff}\nb.cw.orange,.sk-txt b.cw.orange,.sk-sline b.cw.orange{background:#ff9a1f;color:#1d2a44}\nb.cw.brown,.sk-txt b.cw.brown,.sk-sline b.cw.brown{background:#8a5a33;color:#fff}\n.dz-can{font-weight:800;color:#2f7de1}.dz-no{font-weight:800;color:#e03a3a}\n@media (max-width:560px){.dz-art{width:84px;height:72px}.dz-art.dz-fig{width:96px;height:104px}}";document.head.appendChild(s);})();
